import React, { useState, useEffect } from 'react';
import { onSnapshot, deleteDoc } from 'firebase/firestore';
import { getCollectionRef, getDocRef } from '../firebase/config';
import AddCompany from './AddCompany';
import ConfirmDialog from './ConfirmDialog';
import Notification from './Notification';
import useNotification from '../hooks/useNotification';
import './ServiceCenter.css'; // Reusing ServiceCenter styles
import './CompanyManagement.css';

const CompanyManagement = () => {
  const [companies, setCompanies] = useState([]);
  const [showAddCompany, setShowAddCompany] = useState(false);
  const [editingCompany, setEditingCompany] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
  const [confirmDialog, setConfirmDialog] = useState({ isOpen: false, id: null, name: '' });
  const { notification, showNotification, hideNotification } = useNotification();

  useEffect(() => {
    const companiesRef = getCollectionRef('companies');
    const unsubscribeCompanies = onSnapshot(companiesRef, (snapshot) => {
      const companiesArray = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setCompanies(companiesArray);
    });

    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      unsubscribeCompanies();
    };
  }, []);

  const handleDelete = (companyId, companyName) => {
    setConfirmDialog({ isOpen: true, id: companyId, name: companyName || 'this company' });
  };

  const confirmDelete = async () => {
    try {
      const companyRef = getDocRef('companies', confirmDialog.id);
      await deleteDoc(companyRef);
      showNotification('Company deleted successfully!', 'success');
    } catch (error) {
      showNotification('Error deleting company. Please try again.', 'error');
    }
    setConfirmDialog({ isOpen: false, id: null, name: '' });
  };

  const handleEdit = (company) => {
    setEditingCompany(company);
    setShowAddCompany(true);
  };

  const handleAddCompanyClick = () => {
    setEditingCompany(null);
    setShowAddCompany(true);
  };

  const handleBackToCompanies = () => setShowAddCompany(false);

  const handleCompanyAddedOrUpdated = () => {
    setEditingCompany(null);
    setShowAddCompany(false);
  };

  const filteredCompanies = companies.filter(company =>
    company.companyName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    company.contactPerson?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    company.address?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    company.mobileNumber?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (showAddCompany) {
    return (
      <AddCompany
        onBack={handleBackToCompanies}
        onCompanyAddedOrUpdated={handleCompanyAddedOrUpdated}
        editingCompany={editingCompany}
      />
    );
  }

  return (
    <div className="service-center">
      <div className="service-header">
        <h1>Company Management</h1>
        <button className="btn-primary" onClick={handleAddCompanyClick}>
          <span className="btn-icon">+</span> Add New Company
        </button>
      </div>

      <div className="search-bar-section">
        <div className="search-container">
          <span className="search-icon">🔍</span>
          <input
            type="text"
            className="search-input"
            placeholder="Search companies..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        {searchTerm && (
          <button
            className="clear-search-btn"
            onClick={() => setSearchTerm('')}
          >
            ✕
          </button>
        )}
      </div>

      <div className="services-container">
        {filteredCompanies.length > 0 ? (
          <>
            {!isMobile && (
              <div className="table-responsive">
                <table className="services-table">
                  <thead>
                    <tr>
                      <th>Company Name</th>
                      <th>Contact Person</th>
                      <th>Mobile Number</th>
                      <th>Email</th>
                      <th>Created Date</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredCompanies.map(company => (
                      <tr key={company.id} className="service-table-row">
                        <td>
                          <div className="service-info">
                            <div className="service-icon">{company.companyName?.charAt(0).toUpperCase() || 'C'}</div>
                            <div className="service-details">
                              <div className="service-name">{company.companyName}</div>
                            </div>
                          </div>
                        </td>
                        <td>{company.contactPerson || 'N/A'}</td>
                        <td>{company.mobileNumber || 'N/A'}</td>
                        <td>{company.email || 'N/A'}</td>
                        <td>{company.createdAt ? new Date(company.createdAt).toLocaleDateString() : 'N/A'}</td>
                        <td>
                          <div className="action-buttons">
                            <button className="btn-icon btn-edit" onClick={() => handleEdit(company)}>✏️</button>
                            <button className="btn-icon btn-delete" onClick={() => handleDelete(company.id, company.companyName)}>🗑️</button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            {isMobile && (
              <div className="services-cards">
                {filteredCompanies.map(company => (
                  <div key={company.id} className="service-card">
                    <div className="card-header">
                      <div className="service-info">
                        <div className="service-icon">{company.companyName?.charAt(0).toUpperCase() || 'C'}</div>
                        <div className="service-details">
                          <div className="service-name">{company.companyName}</div>
                          {company.contactPerson && <div className="service-id">Contact: {company.contactPerson}</div>}
                        </div>
                      </div>
                      <div className="card-actions">
                        <button className="btn-icon btn-edit" onClick={() => handleEdit(company)}>✏️</button>
                        <button className="btn-icon btn-delete" onClick={() => handleDelete(company.id, company.companyName)}>🗑️</button>
                      </div>
                    </div>

                    <div className="card-content">
                      <div className="card-section">
                        <h4>Contact Information</h4>
                        <div className="service-details-grid">
                          <div className="detail-item full-width">
                            <span className="detail-label">Mobile:</span>
                            <span className="detail-value">{company.mobileNumber || 'N/A'}</span>
                          </div>
                          {company.email && (
                            <div className="detail-item full-width">
                              <span className="detail-label">Email:</span>
                              <span className="detail-value">{company.email}</span>
                            </div>
                          )}
                        </div>
                      </div>

                      {company.address && (
                        <div className="card-section">
                          <h4>Address</h4>
                          <p>{company.address}</p>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </>
        ) : (
          <div className="empty-state">
            <div className="empty-icon">🏢</div>
            <h3>No companies found</h3>
            <p>Try adjusting your search criteria, or add a new company.</p>
          </div>
        )}
      </div>

      <Notification
        message={notification.message}
        type={notification.type}
        isVisible={notification.isVisible}
        onClose={hideNotification}
      />

      <ConfirmDialog
        isOpen={confirmDialog.isOpen}
        title="Delete Company"
        message={`Are you sure you want to delete "${confirmDialog.name}"?`}
        onConfirm={confirmDelete}
        onCancel={() => setConfirmDialog({ isOpen: false, id: null, name: '' })}
        confirmText="Delete"
        cancelText="Cancel"
        type="danger"
      />
    </div>
  );
};

export default CompanyManagement;
