import React, { useState } from 'react';
import './Sidebar.css';

const Sidebar = ({ currentPath, onNavigate, collapsed, hidden, isMobile, onClose, onHide, onFilterChange }) => {
  const [showFilters, setShowFilters] = useState(false);
  const [filters, setFilters] = useState({
    status: 'all',
    category: 'all',
    dateRange: 'all',
    startDate: '',
    endDate: '',
    brand: ''
  });

  const menuItems = [
    { path: '/dashboard', label: 'Dashboard', icon: '📊' },
    { path: '/customers', label: 'Customers', icon: '👥' },
    { path: '/company', label: 'Company', icon: '🏢' },
    { path: '/services', label: 'Service', icon: '🔧' },
    { path: '/tech', label: 'Technician', icon: '👨‍💻' },
    { path: '/tickets', label: 'Tickets', icon: '🎫' },
    { path: '/superadmin', label: 'Super Admin', icon: '👑' }
  ];

  const handleItemClick = (e, path) => {
    // Only prevent default on left-click (button 0)
    if (e.button === 0) {
      e.preventDefault();
      onNavigate(path);
      if (isMobile && onClose) {
        onClose();
      }
    }
  };

  const handleFilterChange = (filterType, value) => {
    const newFilters = { ...filters, [filterType]: value };
    setFilters(newFilters);
    
    // Notify parent component about filter changes
    if (onFilterChange) {
      onFilterChange(newFilters);
    }
  };

  const resetFilters = () => {
    const defaultFilters = {
      status: 'all',
      category: 'all',
      dateRange: 'all',
      startDate: '',
      endDate: '',
      brand: ''
    };
    setFilters(defaultFilters);
    if (onFilterChange) {
      onFilterChange(defaultFilters);
    }
  };

  const isTicketsPage = currentPath === '/tickets';

  return (
    <>
      {isMobile && !collapsed && (
        <div className="sidebar-overlay" onClick={onClose}></div>
      )}
      <div className={`sidebar ${collapsed ? 'collapsed' : ''} ${isMobile ? 'mobile' : ''} ${hidden ? 'hidden' : ''}`}>
        <div className="sidebar-header">
          <h2>{collapsed ? 'AP' : 'Admin Panel'}</h2>
          {!collapsed && (
            <button className="close-sidebar" onClick={isMobile ? onClose : onHide} title="Hide Sidebar">×</button>
          )}
        </div>
        <ul className="sidebar-menu">
          {menuItems.map(item => (
            <li key={item.path}>
              <a
                href={item.path}
                className={currentPath === item.path ? 'active' : ''}
                onClick={(e) => handleItemClick(e, item.path)}
                title={collapsed ? item.label : ''}
              >
                <span className="icon">{item.icon}</span>
                {!collapsed && <span className="label">{item.label}</span>}
              </a>
            </li>
          ))}
        </ul>

        {/* Filter Section - Only show on Tickets page and when not collapsed */}
        {isTicketsPage && !collapsed && (
          <div className="sidebar-filters">
            <div className="filters-header">
              <h3>🔍 Filters</h3>
              <button 
                className="btn-toggle-filters"
                onClick={() => setShowFilters(!showFilters)}
                title={showFilters ? 'Hide Filters' : 'Show Filters'}
              >
                {showFilters ? '▲' : '▼'}
              </button>
            </div>

            {showFilters && (
              <div className="filters-content">
                {/* Brand Search Filter */}
                <div className="filter-group">
                  <label>🏷️ Brand Name</label>
                  <input
                    type="text"
                    value={filters.brand}
                    onChange={(e) => handleFilterChange('brand', e.target.value)}
                    placeholder="Search brand..."
                    className="filter-input"
                  />
                  {filters.brand && (
                    <button
                      className="btn-clear-input"
                      onClick={() => handleFilterChange('brand', '')}
                      title="Clear brand filter"
                    >
                      ✕
                    </button>
                  )}
                </div>

                {/* Status Filter */}
                <div className="filter-group">
                  <label>Status</label>
                  <select 
                    value={filters.status}
                    onChange={(e) => handleFilterChange('status', e.target.value)}
                    className="filter-select"
                  >
                    <option value="all">All Status</option>
                    <option value="pending">Pending</option>
                    <option value="in-progress">In Progress</option>
                    <option value="resolved">Resolved</option>
                    <option value="cancelled">Cancelled</option>
                  </select>
                </div>

                {/* Category Filter */}
                <div className="filter-group">
                  <label>Category</label>
                  <select 
                    value={filters.category}
                    onChange={(e) => handleFilterChange('category', e.target.value)}
                    className="filter-select"
                  >
                    <option value="all">All Categories</option>
                    <option value="demo">Demo</option>
                    <option value="service">Service</option>
                    <option value="third-party">Third Party</option>
                    <option value="in-store">In Store</option>
                    <option value="in-stock">In Stock</option>
                  </select>
                </div>

                {/* Date Range Filter */}
                <div className="filter-group">
                  <label>Date Range</label>
                  <select 
                    value={filters.dateRange}
                    onChange={(e) => handleFilterChange('dateRange', e.target.value)}
                    className="filter-select"
                  >
                    <option value="all">All Time</option>
                    <option value="today">Today</option>
                    <option value="yesterday">Yesterday</option>
                    <option value="last-7-days">Last 7 Days</option>
                    <option value="last-30-days">Last 30 Days</option>
                    <option value="this-month">This Month</option>
                    <option value="last-month">Last Month</option>
                    <option value="custom">Custom Range</option>
                  </select>
                </div>

                {/* Custom Date Range */}
                {filters.dateRange === 'custom' && (
                  <div className="filter-group custom-date-range">
                    <label>Start Date</label>
                    <input
                      type="date"
                      value={filters.startDate}
                      onChange={(e) => handleFilterChange('startDate', e.target.value)}
                      className="filter-input"
                    />
                    <label>End Date</label>
                    <input
                      type="date"
                      value={filters.endDate}
                      onChange={(e) => handleFilterChange('endDate', e.target.value)}
                      className="filter-input"
                    />
                  </div>
                )}

                {/* Active Filters Summary */}
                {(filters.brand || filters.status !== 'all' || filters.category !== 'all' || filters.dateRange !== 'all') && (
                  <div className="active-filters-summary">
                    <div className="summary-header">Active Filters:</div>
                    <div className="summary-tags">
                      {filters.brand && (
                        <span className="filter-tag">
                          🏷️ {filters.brand}
                          <button onClick={() => handleFilterChange('brand', '')}>✕</button>
                        </span>
                      )}
                      {filters.status !== 'all' && (
                        <span className="filter-tag">
                          Status: {filters.status}
                          <button onClick={() => handleFilterChange('status', 'all')}>✕</button>
                        </span>
                      )}
                      {filters.category !== 'all' && (
                        <span className="filter-tag">
                          {filters.category}
                          <button onClick={() => handleFilterChange('category', 'all')}>✕</button>
                        </span>
                      )}
                      {filters.dateRange !== 'all' && (
                        <span className="filter-tag">
                          📅 {filters.dateRange}
                          <button onClick={() => handleFilterChange('dateRange', 'all')}>✕</button>
                        </span>
                      )}
                    </div>
                  </div>
                )}

                {/* Reset Button */}
                <button 
                  className="btn-reset-filters"
                  onClick={resetFilters}
                >
                  🔄 Reset All Filters
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </>
  );
};

export default Sidebar;