import React, { useState, useEffect } from 'react';
import { addDoc, updateDoc } from 'firebase/firestore';
import { getCollectionRef, getDocRef } from '../firebase/config';
import Notification from './Notification';
import useNotification from '../hooks/useNotification';
import './AddService.css'; // Reusing AddService.css for similar styling

const AddCompany = ({ onBack, onCompanyAddedOrUpdated, editingCompany }) => {
  const [formData, setFormData] = useState({
    companyName: '',
    contactPerson: '',
    mobileNumber: '',
    email: '',
    address: '',
    gstNumber: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { notification, showNotification, hideNotification } = useNotification();

  useEffect(() => {
    if (editingCompany) {
      setFormData({
        companyName: editingCompany.companyName || '',
        contactPerson: editingCompany.contactPerson || '',
        mobileNumber: editingCompany.mobileNumber || '',
        email: editingCompany.email || '',
        address: editingCompany.address || '',
        gstNumber: editingCompany.gstNumber || ''
      });
    }
  }, [editingCompany]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    
    // Validate and format mobile number (only digits, max 10)
    if (name === 'mobileNumber') {
      const digitsOnly = value.replace(/\D/g, '');
      const limitedDigits = digitsOnly.slice(0, 10);
      setFormData(prev => ({ ...prev, [name]: limitedDigits }));
      return;
    }
    
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate mobile number (exactly 10 digits if provided)
    if (formData.mobileNumber && formData.mobileNumber.length !== 10) {
      showNotification('Mobile number must be exactly 10 digits', 'error');
      return;
    }
    
    setIsSubmitting(true);

    try {
      const companyData = {
        ...formData,
        createdAt: editingCompany ? editingCompany.createdAt : new Date().toISOString()
      };

      if (editingCompany) {
        // Update existing company
        const companyRef = getDocRef('companies', editingCompany.id);
        await updateDoc(companyRef, companyData);
        showNotification('Company updated successfully!', 'success');
      } else {
        // Add new company
        const companiesRef = getCollectionRef('companies');
        await addDoc(companiesRef, companyData);
        showNotification('Company added successfully!', 'success');
      }

      onCompanyAddedOrUpdated();
    } catch (error) {
      console.error('Error saving company:', error);
      showNotification('Error saving company. Please try again.', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="add-service">
      <div className="technicians-header">
        <h1>{editingCompany ? 'Edit Company' : 'Add New Company'}</h1>
        <button type="button" className="btn-primary" onClick={onBack}>
          <span className="btn-icon">←</span> Back to Companies
        </button>
      </div>

      <div className="add-service-container">
        <div className="add-service-card">
          <form onSubmit={handleSubmit}>
            <div className="form-section">
              <h3>Company Information</h3>
              <div className="form-grid">
                <div className="form-group full-width">
                  <label>Company Name *</label>
                  <input
                    type="text"
                    name="companyName"
                    value={formData.companyName}
                    onChange={handleInputChange}
                    required
                    placeholder="Enter company name"
                  />
                </div>

                <div className="form-group">
                  <label>Contact Person</label>
                  <input
                    type="text"
                    name="contactPerson"
                    value={formData.contactPerson}
                    onChange={handleInputChange}
                    placeholder="Enter contact person name"
                  />
                </div>

                <div className="form-group">
                  <label>Mobile Number</label>
                  <input
                    type="tel"
                    name="mobileNumber"
                    value={formData.mobileNumber}
                    onChange={handleInputChange}
                    placeholder="Enter 10 digit mobile number"
                    pattern="[0-9]{10}"
                    maxLength="10"
                  />
                  {formData.mobileNumber && formData.mobileNumber.length !== 10 && (
                    <small style={{color: '#ef4444', display: 'block', marginTop: '0.25rem'}}>
                      Must be 10 digits
                    </small>
                  )}
                </div>

                <div className="form-group">
                  <label>Email Address</label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    placeholder="Enter email address"
                  />
                </div>

                <div className="form-group">
                  <label>GST Number</label>
                  <input
                    type="text"
                    name="gstNumber"
                    value={formData.gstNumber}
                    onChange={handleInputChange}
                    placeholder="Enter GST number"
                  />
                </div>

                <div className="form-group full-width">
                  <label>Address</label>
                  <textarea
                    name="address"
                    value={formData.address}
                    onChange={handleInputChange}
                    rows="3"
                    placeholder="Enter complete address"
                  />
                </div>
              </div>
            </div>

            <div className="form-actions">
              <button type="submit" className="btn-primary" disabled={isSubmitting}>
                {isSubmitting ? (editingCompany ? 'Updating Company...' : 'Adding Company...') :
                 (editingCompany ? 'Update Company' : 'Add Company')}
              </button>
              <button type="button" className="btn-secondary" onClick={onBack} disabled={isSubmitting}>
                Cancel
              </button>
            </div>
          </form>
        </div>
      </div>

      <Notification
        message={notification.message}
        type={notification.type}
        isVisible={notification.isVisible}
        onClose={hideNotification}
      />
    </div>
  );
};

export default AddCompany;
