// src/components/SuperAdminLogin.js
import React, { useState, useEffect } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase/config';
import './SuperAdminLogin.css';

const SuperAdminLogin = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isMounted, setIsMounted] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    setIsMounted(true);
    
    // If already logged in as superadmin, redirect directly
    const checkSession = () => {
      const superAdmin = localStorage.getItem('superAdmin');
      if (superAdmin) {
        try {
          const adminData = JSON.parse(superAdmin);
          if (adminData.role === 'superadmin') {
            navigate('/superadmin');
          }
        } catch (e) {
          // ignore
        }
      }
    };
    checkSession();

    return () => setIsMounted(false);
  }, [navigate]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    const normalizedEmail = email.trim().toLowerCase();
    
    // Explicit Credential Check
    if (normalizedEmail !== 'superadmin123@gmail.com' || password !== 'superadmin123') {
      if (isMounted) {
        setError('Access Denied. Invalid Super Admin credentials.');
        setLoading(false);
      }
      return;
    }

    try {
      let user;
      
      // 1. Attempt standard Firebase Auth Login
      try {
        console.log('🔐 Attempting standard Super Admin Firebase sign-in...');
        const userCredential = await signInWithEmailAndPassword(auth, normalizedEmail, password);
        user = userCredential.user;
      } catch (authError) {
        console.warn('⚠️ Firebase sign-in failed. Error code:', authError.code);
        
        // 2. If user is not found, automatically register this special account
        if (authError.code === 'auth/user-not-found' || authError.code === 'auth/invalid-credential') {
          console.log('🆕 Special account not found in Auth. Automatically registering...');
          try {
            const userCredential = await createUserWithEmailAndPassword(auth, normalizedEmail, password);
            user = userCredential.user;
            console.log('✅ Registered new Super Admin Firebase Auth account.');
          } catch (createError) {
            console.error('❌ Failed to register Super Admin Firebase Auth user:', createError);
            throw new Error('Authentication failed. Failed to register the Super Admin account.');
          }
        } else {
          throw authError;
        }
      }

      // 3. Store Super Admin session locally
      const superAdminSession = {
        email: user.email,
        uid: user.uid,
        role: 'superadmin',
        name: 'Super Admin'
      };
      
      localStorage.setItem('superAdmin', JSON.stringify(superAdminSession));
      
      // 4. Save/Sync user document in Firestore to satisfy path security rules
      try {
        const userDocRef = doc(db, 'mainData', 'Billuload', 'users', user.uid);
        await setDoc(userDocRef, {
          email: user.email,
          uid: user.uid,
          role: 'superadmin',
          name: 'Super Admin',
          lastLogin: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        }, { merge: true });
        console.log('✅ Super Admin user document saved in Firestore.');
      } catch (firestoreError) {
        console.error('⚠️ Firestore user document write failed:', firestoreError);
      }

      // 5. Navigate to Dashboard
      if (isMounted) {
        setTimeout(() => {
          navigate('/superadmin');
        }, 100);
      }

    } catch (err) {
      console.error('❌ Super Admin Authentication error:', err);
      if (isMounted) {
        setError(err.message || 'An error occurred during Super Admin verification.');
      }
    } finally {
      if (isMounted) {
        setLoading(false);
      }
    }
  };

  return (
    <div className="sa-login-bg">
      <div className="sa-login-box">
        <div className="sa-glow sa-glow-1"></div>
        <div className="sa-glow sa-glow-2"></div>
        
        <div className="sa-card-content">
          <div className="sa-badge">👑 SYSTEM CONTROL</div>
          <h1 className="sa-title">Super Admin Portal</h1>
          <p className="sa-subtitle">Authorized personnel only. Please verify your credentials.</p>

          <form onSubmit={handleSubmit} className="sa-form">
            <div className="sa-input-wrapper">
              <span className="sa-input-icon">👤</span>
              <input
                type="email"
                placeholder="Super Admin Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                disabled={loading}
                required
              />
            </div>
            
            <div className="sa-input-wrapper">
              <span className="sa-input-icon">🔒</span>
              <input
                type="password"
                placeholder="Security Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                disabled={loading}
                required
              />
            </div>

            {error && (
              <div className="sa-error-container">
                <span className="sa-error-icon">⚠️</span>
                <span className="sa-error-text">{error}</span>
              </div>
            )}

            <button type="submit" className="sa-btn-login" disabled={loading}>
              {loading ? (
                <div className="sa-spinner-wrapper">
                  <div className="sa-spinner"></div>
                  <span>Authenticating...</span>
                </div>
              ) : (
                'Grant Access'
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default SuperAdminLogin;
